package main

import "fmt"

type Node struct {
    Val  int
    Next *Node
}

func reverse(head *Node) *Node {
    var prev *Node
    curr := head
    for curr != nil {
        next := curr.Next // guarda el siguiente
        curr.Next = prev  // invierte el enlace
        prev = curr       // avanza prev
        curr = next       // avanza curr
    }
    return prev // nueva cabeza
}

func main() {
    head := &Node{1, &Node{2, &Node{3, nil}}}
    for n := reverse(head); n != nil; n = n.Next {
        fmt.Print(n.Val, " ")
    }
    // Salida: 3 2 1
}
```

**Cómo funciona**
1. `prev` empieza en `nil`, porque el primer nodo pasará a ser el último.
2. En cada vuelta guardas `curr.Next`, apuntas `curr` hacia atrás (`prev`) y avanzas los dos punteros.
3. Cuando `curr` es `nil`, `prev` apunta al último nodo original, que ahora es la cabeza.

Tiene coste O(n) en tiempo y O(1) en memoria.

