func reverseListRecursive(head *Node) *Node {
	return reverseHelper(head, nil)
}

func reverseHelper(curr *Node, prev *Node) *Node {
	if curr == nil {
		return prev
	}

	next := curr.Next
	curr.Next = prev
	return reverseHelper(next, curr)
}
```

## Ejemplo de uso:

```go
